actions.expression:
{run(() =>
                  onAiPreset(
                    t('appTranslateSelectionPrompt', {
                      lang: t(appLangKey(code)),
                      text: selectedText,
                    }),
                  ),
                )}

{() => {
              collapse.onTabPress(tab === tabName)
              lastRegularTab.current = tabName
              setTab(tabName)
              setDropdown(null)
            }}

{(v) => {
                        if (!canEdit) return
                        editor
                          .chain()
                          .focus()
                          .updateAttributes('docProtected', { imageWrap: v || null })
                          .run()
                      }}

{() => {
                          if (!canEdit) return
                          editor
                            .chain()
                            .focus()
                            .updateAttributes('docProtected', {
                              imageAlign: value === 'left' ? null : value,
                            })
                            .run()
                        }}

{() => {
                            editor.view.focus()
                            enterSelectedTable(editor.state, editor.view.dispatch)
                            selectTablePart(kind)(editor.state, editor.view.dispatch)
                            setDropdown(null)
                          }}

{(e) => {
                        if (e.nativeEvent.isComposing) return
                        if (e.key === 'Enter') {
                          e.preventDefault()
                          commitSize(e.currentTarget.value)
                        } else if (e.key === 'Escape') {
                          e.preventDefault()
                          e.stopPropagation()
                          setSizeDraft(null)
                          setDropdown(null)
                          chain().run()
                        }
                      }}

{() =>
                        setTextStyle({
                          highlight: fs.highlight === penHighlight ? null : penHighlight,
                        })
                      }

{(hex) => {
                          if (!hex) {
                            setPenColor(null)
                            setTextStyle({ color: null })
                          } else {
                            setPenColor(hex)
                            setTextStyle({ color: hex })
                          }
                        }}

{() =>
                              setParaAttr({ lineSpacing: s, lineRule: null, lineRawTwips: null })
                            }

{(e) => {
          const v = Math.round(Number(e.target.value))
          set(Number.isFinite(v) ? Math.min(max, Math.max(1, v)) : 1)
        }}

{() => {
                            // Word parity: arm crosshair draw mode (click = default 1in
                            // square, drag = custom size, Shift = square, Esc = cancel)
                            startShapeDrawMode(editor, s.prst, (opts) =>
                              insertShapeAt(editor, s.prst, opts),
                            )
                            setDropdown(() => null)
                          }}

{() => {
                    setDropdown(() => null)
                    startShapeDrawMode(editor, 'rect', (opts) => insertTextboxAt(editor, opts), {
                      clickSize: { widthEmu: TEXTBOX_WIDTH_EMU, heightEmu: TEXTBOX_HEIGHT_EMU },
                      ghost: { fill: 'rgba(255,255,255,0.6)', border: '#000000' },
                      onInserted: (pos) => focusTextboxEditorAt(editor, pos),
                    })
                  }}

{() => {
                    setDropdown(() => null)
                    const pos = insertTextboxAt(editor)
                    if (pos != null) {
                      requestAnimationFrame(() => focusTextboxEditorAt(editor, pos))
                    }
                  }}

{() => {
                      setDropdown(() => null)
                      const newDropCap = opt.val
                        ? JSON.stringify({ type: opt.val, lines: 3 })
                        : null
                      setParaAttrs(editor, { dropCap: newDropCap })
                    }}

{() => {
                      // Word gallery semantics: replace the area's content with a single page-number paragraph
                      const hf: HeaderFooter = {
                        text: '#',
                        pageNumber: true,
                        paras: [{ align, runs: [{ text: '#' }] }],
                      }
                      ;(kind === 'header' ? onHeader : onFooter)(hf)
                      setDropdown(() => null)
                    }}

{() => {
                    if (hfHasPageField(footer)) onFooter(hfWithoutPageMarks(footer!))
                    if (hfHasPageField(header)) onHeader(hfWithoutPageMarks(header!))
                    setDropdown(() => null)
                  }}

{(e) => {
            const raw = e.target.value.trim()
            const pt = raw === '' ? 0 : Math.min(400, Math.max(0, Number(raw)))
            if (Number.isFinite(pt)) {
              // clamped input keeps the typed text (uncontrolled): sync it back
              if (String(pt) !== raw) e.target.value = String(pt)
              if (Math.round(pt * 20) !== twips) commitPara(attr, Math.round(pt * 20))
            }
            releaseTarget(e)
          }}

{(w, h, scope) => {
            // typed dimensions decide the orientation flag (Word flips the radio); a square keeps it
            const orientation = w === h ? section.orientation : w > h ? 'landscape' : 'portrait'
            if (scope === 'document') {
              onPaperSizeAll(Math.min(w, h), Math.max(w, h), orientation)
            } else {
              onSection({ ...section, pageWidth: w, pageHeight: h, orientation })
            }
          }}

{() => {
                      setDropdown(() => null)
                      if (hasRangeSelection()) {
                        onAiPreset(
                          t('ribbonTranslateSelectionPrompt', { lang: t(ribbonLangKey(code)) }),
                        )
                      } else if (confirmAiRewrite()) {
                        onAiPreset(t('ribbonTranslatePrompt', { lang: t(ribbonLangKey(code)) }))
                      }
                    }}

{() => {
            // Names scoped to another sheet resolve to #NAME? here; only
            // workbook-scoped and active-sheet names are usable in a formula.
            const data = onGetDefinedNames()
            return data.names
              .filter(
                (entry) => entry.scopeSheetId === null || entry.scopeSheetId === data.activeSheetId,
              )
              .map((entry) => entry.name)
          }}

{(text, atts) => {
            if (aiBusy) return false
            onSend(text, atts)
            return true
          }}

{(request) => {
                const failure = onCreatePivot(request)
                if (failure === null) openPivotPane()
                return failure
              }}

{(model) =>
            setPivotPane(
              pivotPane.deferred
                ? { ...pivotPane, model, dirty: true, error: null }
                : applyPivotModel(pivotPane, model),
            )
          }

{(beforeId, copy) => {
            void actions.moveOrCopy(targets, beforeId, copy).then(() => {
              if (copy) setGroup([])
            })
          }}

{(event) => {
        if (event.key === 'Enter') {
          event.preventDefault()
          commit()
          event.currentTarget.blur()
        } else if (event.key === 'Escape') {
          cancelledRef.current = true
          setValue(name)
          event.currentTarget.blur()
        }
        event.stopPropagation()
      }}

entries.expression:
largeMenu(
            t('appGroupThemes'),
            '🎨',
            t('appThemesTitle'),
            THEME_PRESETS.map((preset) => ({
              value: `page-layout:theme:${preset.id}`,
              label: preset.name,
            })),
            !themeEditingAvailable,
          )

largeMenu(
            t('appMargins'),
            '⿴',
            t('appMarginsTitle', {
              value: pageLayout.margins ? marginLabels[pageLayout.margins] : t('appAsSavedInFile'),
            }),
            [
              { value: 'page-layout:margins:normal', label: t('appMarginNormal') },
              { value: 'page-layout:margins:wide', label: t('appMarginWide') },
              { value: 'page-layout:margins:narrow', label: t('appMarginNarrow') },
            ],
          )

largeMenu(
            t('appOrientationLabel'),
            '⤢',
            t('appOrientationTitle', {
              value: pageLayout.orientation
                ? t(pageLayout.orientation === 'portrait' ? 'appPortrait' : 'appLandscape')
                : t('appAsSavedInFile'),
            }),
            [
              { value: 'page-layout:orientation:portrait', label: t('appPortrait') },
              { value: 'page-layout:orientation:landscape', label: t('appLandscape') },
            ],
          )

actions.expression:
{(event) => {
            if (event.key === 'Enter') {
              event.currentTarget.blur() // blur handler commits
            } else if (event.key === 'Escape') {
              setDraft(null)
              event.currentTarget.blur()
            }
          }}

{(event) => {
            // focus moved into the dropdown → let the option click win
            if (wrapRef.current?.contains(event.relatedTarget as Node)) return
            commitDraft()
          }}

{(value) => {
        const category = numberFormatCategories().find((candidate) => candidate.label === value)
        if (category) onCommand(`format:${category.pattern}`)
      }}
